"""Preserve rejected raster translation and qualified exact crop preparation."""
import csv,json,sys
from datetime import datetime,timedelta,timezone
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'src'))
from smart_parking.provenance import digest
E=ROOT/'experiments/evidence/HEARTBEAT-20261027T000906Z'
def read(p):return json.loads(p.read_text(encoding='utf-8-sig'))
def dump(p,v):p.write_text(json.dumps(v,indent=2)+'\n',encoding='utf-8')
def append(path,title,body):
    p=ROOT/path;t=p.read_text(encoding='utf-8');assert title not in t;p.write_text(t.rstrip()+'\n\n'+title+'\n\n'+body+'\n',encoding='utf-8')

def main():
    assert not (E/'checks.json').exists();now=datetime.now(timezone.utc).isoformat();s=read(ROOT/'data/automation_state.json');r=read(ROOT/'models/exact_crop_cache_validation.json');failed=read(ROOT/'models/exact_crop_cache_v1_failed.json');assert r['run_id'].startswith('EXACT-CROP-CACHE-V2-')
    assert s['completed_recorded_runs_since_schedule']==len(set(s['completed_run_ids']))==94 and not s['active_training_jobs'] and not s['active_validation_jobs']
    assert not failed['implementation_gate_passed'] and failed['first_mismatch']['differing_channels']==7 and r['pixel_mismatches']==0 and r['real_crops']==9746 and r['synthetic_fixture_cases']==2000
    for result in [failed,r]:
        pth=ROOT/'experiments/results'/result['run_id']/'protocol.json';p=read(pth);assert digest(pth)==result['protocol_sha256']
        for name,h in {**p['input_hashes'],**p['source_hashes'],**p['protected_hashes']}.items():assert digest(ROOT/name)==h,name
    manifest=read(ROOT/r['cache_manifest']);assert digest(ROOT/r['cache_manifest'])==r['cache_manifest_sha256'] and len(manifest['records'])==9746 and len(manifest['chunks'])==266
    for chunk in manifest['chunks']:assert digest(ROOT/chunk['path'])==chunk['sha256']
    frozen=read(ROOT/'experiments/evidence/HEARTBEAT-20261026T233906Z/checks.json')['frozen_hashes_unchanged']
    for name,h in frozen.items():assert digest(ROOT/name)==h,name
    tests=(E/'unit_tests_final.txt').read_text(encoding='utf-8-sig');assert 'Ran 422 tests' in tests and tests.rstrip().endswith('OK')
    live=read(ROOT/'data/processed/singapore_prospective/summary.json');health=read(ROOT/'reports/singapore_issuance_health_latest.json');issuance=read(ROOT/'reports/singapore_issuance_latest.json');snapshots=len(list((ROOT/'data/raw/singapore_live').glob('*.json')));assert snapshots==66 and health['status']=='healthy' and not health['target_json_decoded'] and not health['performance_evaluated']
    receipts=[json.loads(line) for line in (ROOT/'data/resource_receipts.jsonl').read_text(encoding='utf-8').splitlines()];last=next(x for x in reversed(receipts) if x['source_id']=='SRC-LIVE-001');nexttime=(datetime.fromisoformat(live['checked_at'])+timedelta(minutes=30)).isoformat()
    s['scheduled_wakeups_completed']+=1;s['last_wakeup_completed_at']=now;s['prospective_live_summary']=live;s['singapore_issuance_health'].update(metadata_status='healthy',status='healthy',raw_files_hashed_once=health['raw_files_hashed_once'],performance_evaluated=False,forecasts_logged=health['forecasts_logged'],global_origins=health['global_origins']);s['exact_crop_cache_validation']=r
    s['next_actions']=[
        'Collect once AFTER '+nexttime+' using collect_singapore_study.py;routine receipt-health WITHOUT --record-trial.66actual snapshots;14079learned forecasts/13origins healthy/unscored. The00:39wake is early relative to00:41due:do useful preparation first,never bypass cadence or backfill.',
        ('Exact crop cache qualified: '+r['cache_manifest']+' SHA256='+r['cache_manifest_sha256']+'. All9746development RGBcrops equal original bytes,all266cache roundtrips pass,sourcehelper speedratio='+str(r['reference_to_local_time_ratio'])+'. ' if r['implementation_gate_passed'] else 'V2 exactness passed but performance gate failed;cache not selected. ')+ 'V1translatedmask failed7RGBchannels despite2000fixture passes;do NOTuse local_crops.crop_slot_local. Qualifiedhelper is exact_crops.crop_slot_exact;originallayout.py unchanged.422softwaretests/counter94/next100checkpoint100/noactivejobs.',
        'Highest-impact next bounded model hypothesis: representation adaptation beyond failed frozen head. FIRST prepare old PKLot RGB crops from models/occupancy_expansion_data_card.json -> data/manifests/occupancy_expansion_v1.json,with source/image/XML hashes,explicit known-label filtering and consumed-camera/date guard. Match cached original feature-row identities from models/occupancy_expansion_candidate.json;expect10104TRAIN/2028reusedDEV;do not open old final groups. This is routine model data preparation,not a run per crop.',
        'Then prespecify ONE warm-start layer4+fc adaptation from models/checkpoints/acpds_balanced/ACPDS-BALANCED-HEAD-20261026T234728842213Z/candidate.pt (SHA256d930f14a74fd11647227814c058eba7496846f6653e0488d4c08a9d67cd5c696),with lower layers/BN frozen,TRAIN-only source balancing,small epoch/time budget,cancellable checkpoints,validation-based selection and unchanged source/PKLot identity-retention gates. No optimizer/crop/threshold grid or retrospective gate changes. Current93.0672%/31confidentfalsevacants sourcehead still fails readiness;TESTwhole27images/alllots/views/aliases remainsclosed until passed DEV plus tested durable claim/frozenfinal protocol.',
        'Independent region-data qualification remains useful. Current public CNRsite timedout and NDISpublisher text established no new individual-content grant;both remainunqualified/no pixels. ACPDS bay polygons are not exhaustive parking-area/background labels. Do not manufacture full segmentation truth from them. Existing strong conditional-region result is known-camera geometry-dependent,not promotedautomaticregionmodel.',
        'SG final CLOSED until2026-10-27T10:51UTC(16:21IST). No interim learned target/matching/error/coverage decoding,refit/backdating/backfill. Existing once-only scorer/globalclaim atclosure. Rollingpersistence58802outcomes/MAE5.571953334920581spaces is separate/not camera accuracy. SoftwareREADY451-file demo/datedPDF preserved;official/manual/physicaloffline/newmachine/student acceptance remainsopen.'
    ];dump(ROOT/'data/automation_state.json',s)
    inventory=read(ROOT/'data/dataset_inventory.json');inventory.update(inventoried_at=now,exact_crop_cache_v1_failed=failed,exact_crop_cache_validation=r)
    for row in inventory['datasets']:
        if row.get('source_id')=='SRC-DS-021':row.update(exact_crop_cache_validation=r,rejected_translated_mask_trial=failed['run_id'],crop_cache_selected=r['implementation_gate_passed'],scientific_accuracy_unchanged=True)
        if row.get('source_id')=='SRC-LIVE-001':row.update(snapshot_count=snapshots,raw_path=last['local_path'],provider_timestamp=last.get('provider_timestamp'),latest_prospective_summary=live,prospective_baseline_scored_outcomes=live['scores_total'],prospective_baseline_mae_spaces=live['baseline_mae_spaces'],forecast_target_coverage=live['forecast_coverage'],learned_issuance_metadata=s['singapore_issuance_health'])
    dump(ROOT/'data/dataset_inventory.json',inventory)
    source=ROOT/'data/source_manifest.csv'
    with source.open(encoding='utf-8-sig',newline='') as f:reader=csv.DictReader(f);fields=reader.fieldnames;rows=list(reader)
    assert len(rows)==len({row['source_id'] for row in rows})==63
    for row in rows:
        if row['source_id']=='SRC-DS-021':row['used_by']+=';'+failed['run_id']+';'+r['run_id'];row['modifications']+=';exact-reference96RGB crop cache;V1translation mismatch preserved,V2fullmask/localRGB';row['status']+=';crop cache implementation gate='+str(r['implementation_gate_passed'])+';no new model score'
    with source.open('w',encoding='utf-8',newline='') as f:writer=csv.DictWriter(f,fieldnames=fields);writer.writeheader();writer.writerows(rows)
    import PIL,numpy,platform
    dump(E/'runtime_versions.json',dict(recorded_at=now,python=sys.version,platform=platform.platform(),pillow=PIL.__version__,numpy=numpy.__version__,purpose='Local software equivalence/performance environment;not an inference speed benchmark'))
    dump(E/'collection_and_health.json',dict(snapshot_receipt=last,snapshots=snapshots,baseline_scores_added=live['scores_added'],baseline_scores_total=live['scores_total'],baseline_mae_spaces=live['baseline_mae_spaces'],study_issuance=issuance['study_issuance'],health=health,next_collection_after=nexttime))
    title='## 27 October 2026 IST / rejected raster translation and exact crop-cache validation'
    body=('The first implementation candidate moved the polygon mask into a local drawing canvas. Five unit tests and 2,000 synthetic fixtures passed, but real TRAIN image GOPR6550.JPG, slot 9, differed in seven RGB channel values. The completed early-rejection trial is recorded as failed, with the original exception log, source, protocol and three finished image proofs (45 crops) preserved. No failed cache was selected. Its 6.928-second duration is the measured outer command wall time including startup. The small pixel difference was treated as an equivalence failure; no model was rerun to excuse it.\n\n'
          'The revised helper retains the original full-size polygon mask and restricts only RGB paste/copy work to the bounding box. It checks all 9,746 real development crops across 266 images plus a new 2,000-case seed-158 synthetic suite. All real crops match the original bytes exactly; all cache files round-trip exactly. Measured crop-function time was '+f"{r['reference_crop_seconds']:.3f}"+' seconds for the reference and '+f"{r['local_crop_seconds']:.3f}"+' seconds for the revision, a ratio of '+f"{r['reference_to_local_time_ratio']:.2f}"+'. The gate required at least two. Comparison order alternated, and image decoding, hashing and NPZ encoding were excluded from those function timers. Total invocation time was '+f"{r['duration_seconds_this_invocation']:.3f}"+' seconds. These are process-local preparation timings, not full application inference performance or measured process RSS. A full-size mask allocation remains. Cache implementation gate='+str(r['implementation_gate_passed'])+'.\n\n'
          'The validated cache contains 7,842 TRAIN and 1,904 validation crops, with explicit labels, original image/layout hashes and per-crop/file SHA256. It occupies '+str(r['cached_rgb_bytes'])+' compressed bytes. Candidate cache: '+r['cache_manifest']+'. It enables later bounded model work with unchanged crop inputs. The original application helper, production weights, best research checkpoint and every final reservation remain unchanged. Scientific accuracy was not evaluated; the earlier 93.0672%/31-false-vacancy model still fails source readiness.\n\n'
          'Eight new synthetic regression/contract tests bring the full software suite to 422 passing tests. Two distinct implementation trials raise the completed counter 92 -> 94: one rejected translation and one revised full-mask/local-RGB validation. Individual fixture cases, crops and cache files are not runs. Wakeups completed 62, source IDs 63, next separate 100-run live checkpoint 100, no active jobs. Current primary CNR publisher access timed out and NDIS publisher text established no new content-rights grant; those source images remain unadmitted. No new source or model accuracy claim follows.\n\n'
          'Official Singapore snapshot 66 adds 1,167 rolling persistence outcomes (58,802 total; MAE 5.571953 spaces) and 1,212 baseline forecasts. Another 1,113 genuine learned forecasts were frozen, giving 14,079 forecasts and 13 origins with healthy receipts. Learned targets, matching, coverage and error remain closed until 27 October 10:51 UTC. Next collection after '+nexttime+'. Next prepare hash-checked old PKLot RGB training/retention crops, then design one bounded last-block representation adaptation. Keep TEST closed and avoid repeating a parameter grid. See docs/EXACT_CROP_CACHE_GUIDE.md. Official/manual/student/physical-offline/new-machine acceptance remains open.')
    for name in ['docs/AUTONOMOUS_PROGRESS.md','docs/PROJECT_PROGRESS.md','docs/IMPLEMENTATION_STATUS.md','docs/TEST_RESULTS.md']:append(name,title,body)
    append('docs/EXACT_CROP_CACHE_GUIDE.md',title,'Completed revised trial '+r['run_id']+' has zero byte mismatches on 9,746 real crops and 2,000 synthetic fixtures. The measured crop-time ratio is '+f"{r['reference_to_local_time_ratio']:.2f}"+'; implementation gate='+str(r['implementation_gate_passed'])+'. Full evidence:models/exact_crop_cache_validation.json. Rejected V1:models/exact_crop_cache_v1_failed.json. No production helper or scientific result changed.')
    append('docs/SOURCE_REGISTRY.md',title,'Source identities remain 63. SRC-DS-021 development imagery supports byte-equivalence validation and derived RGB cache only; publisher TEST remains closed. Original author/MIT attribution remains unchanged. Current CNR access timeout and NDIS page consultation did not establish new individual-content permission; data/resource rights statuses are unchanged. No new images, labels or rights from those two sources were admitted.')
    req=ROOT/'docs/REQUIREMENTS.csv'
    with req.open(encoding='utf-8-sig',newline='') as f:reader=csv.DictReader(f);fields=reader.fieldnames;rows=list(reader)
    for row in rows:
        if row['requirement_id']=='DATA-02':row['actual_evidence']+=';models/exact_crop_cache_validation.json;models/exact_crop_cache_v1_failed.json';row['test_result']+=';9746realcrop bytes/266cache roundtrips exact;V1pixel failure preserved'
        if row['requirement_id']=='QA-02':row['test_result']+=';422softwaretests;8new raster regression/contract fixtures;two implementation trials,not per-crop/model accuracy'
    with req.open('w',encoding='utf-8',newline='') as f:writer=csv.DictWriter(f,fieldnames=fields,quoting=csv.QUOTE_ALL);writer.writeheader();writer.writerows(rows)
    dump(E/'checks.json',dict(checked_at=now,counter_before=92,counter_after=94,completed_trials=[failed['run_id'],r['run_id']],wakeups_completed=62,unique_sources=63,software_tests=422,frozen_hashes_unchanged=frozen,cache_gate=r['implementation_gate_passed'],cache_manifest_sha256=r['cache_manifest_sha256'],real_crops=9746,synthetic_fixture_cases=2000,pixel_mismatches=0,model_calls=0,final_opened=False,active_jobs=[],next100_run_checkpoint=100,next_collection_after=nexttime,full_project_complete=False))
    print(json.dumps(dict(counter=94,tests=422,cache_gate=r['implementation_gate_passed'],time_ratio=r['reference_to_local_time_ratio'],next_collection=nexttime)))

if __name__=='__main__':main()
